"""The base models of every pyDEXPI class: hand-written, never generated.

``pydexpi_classes.py`` is generated by pyDEXPI-builder
(https://github.com/process-intelligence-research/pyDEXPI-builder) from the DEXPI specification.
This module is **not**: the builder imports it and never writes it. A fresh builder
output is therefore not self-contained on purpose. What lives here is pyDEXPI's infrastructure,
not the specification's:

- ``make_id``, the id every object gets when a source document names none;
- ``PyDexpiBaseModel``: identity hashing, the ``__eq__`` / ``__repr__`` / ``__str__`` cycle
  guards (a model with a reference cycle, like every process model's Stream-Port pair, would
  otherwise recurse forever), and ``__deepcopy__`` keeping one object per object;
- ``PyDexpiDataTypeBaseModel``: field-wise, order-aware value equality with a hash consistent
  with it, and the unit-resolution hook that lets a physical quantity be written as well as read.

Change them here. ``tests/test_pydexpi_classes/test_base_models.py`` fails if the generated file
ever defines them again.
"""

from __future__ import annotations

import functools
import threading
import uuid
from abc import ABC
from copy import copy, deepcopy
from enum import Enum
from typing import Any, get_origin

from pydantic import BaseModel, ConfigDict, Field, model_serializer, model_validator
from pydantic_core import PydanticUndefined

# Relative, and to a module that imports nothing from pydexpi: this file is imported while
# the pydexpi package itself is still initializing, so an absolute import would be circular.
from .unit_resolution import qualified_unit_name, resolve_unit


@functools.cache
def _unit_base() -> type:
    """The generated ``PhysicalQuantityUnit`` enum, looked up the first time a unit is handled.

    The generated module imports this one, so it cannot be imported here while loading. The unit
    hook below only runs once both are loaded (validating or serializing a model), so a lookup on
    first use is always safe, and cached after it.
    """
    from .pydexpi_classes import PhysicalQuantityUnit

    return PhysicalQuantityUnit


def make_id() -> str:
    """Generate a new unique ID for a pyDEXPI object."""
    return f"id_{uuid.uuid4().hex}"


# Objects whose repr is currently being rendered, per thread. Used by
# `PyDexpiBaseModel.__repr__` to cut reference cycles; see the comment there.
_repr_state = threading.local()

# Pairs of objects currently being compared, per thread. Used by `PyDexpiBaseModel.__eq__` to
# cut reference cycles in the same way; see the comment there.
_eq_state = threading.local()


class PyDexpiBaseModel(ABC, BaseModel):
    """Base Model for the classes created for the dexpi data model, containing some overarching functionality"""

    # Model configurations
    model_config = ConfigDict(validate_assignment=True, extra="forbid")

    # Object ID, defaults to a uuid if not specified
    id: str = Field(default_factory=make_id)

    # Hash function
    def __hash__(self) -> int:
        """Compute object hash from id and type for object-based comparisons."""
        # Return hash value based on both id and type
        return hash((self.id, type(self)))

    def __eq__(self, other: object) -> bool:
        """Compare like Pydantic, field by field, but survive reference cycles.

        Pydantic compares nested models recursively, and so follows references as well as
        compositions. On a reference cycle -- every process model has one, ``Stream.source`` /
        ``Stream.target`` and ``Port.connectorReference`` being required references to each
        other -- comparing an object with a copy of itself recursed until ``RecursionError``.

        The comparison is co-inductive: a pair of objects met again while it is still being
        compared further up is taken as equal *for this comparison*, and its fields decide the
        result where the pair was first met. If anything else on the cycle differs, that
        difference still makes the outer comparison false. The guard is per thread and held
        across the whole nested comparison, like the one in `__repr__`.

        `__hash__` is unaffected: it is the id and the class, and equal objects share both,
        because ``id`` is a field.

        Parameters
        ----------
        other : object
            The object to compare with.

        Returns
        -------
        bool
            Pydantic's result: the same class and every field equal.
        """
        if self is other:
            return True
        active = getattr(_eq_state, "active", None)
        if active is None:
            active = _eq_state.active = set()

        marker = (id(self), id(other))
        if marker in active:
            return True

        active.add(marker)
        try:
            return super().__eq__(other)
        finally:
            active.discard(marker)

    def __repr__(self) -> str:
        """Render like Pydantic, but stop at an object already being rendered.

        DEXPI models contain reference cycles by design: `Stream.source` / `Stream.target` and
        `Port.connectorReference` are required references to each other, so every process model
        has one. Pydantic's repr walks nested models unconditionally, so printing any object on
        such a cycle -- in a debugger, a log line, a pytest assertion message -- recurses until
        it raises `RecursionError`.

        Re-entering the same object emits `ClassName(id='...', ...)` instead of descending again.
        The guard is per-thread and spans the whole nested render, not just this frame, because
        the recursion happens while the caller reprs the values this returns.
        """
        active = getattr(_repr_state, "active", None)
        if active is None:
            active = _repr_state.active = set()

        marker = id(self)
        if marker in active:
            return f"{self.__repr_name__()}(id={getattr(self, 'id', None)!r}, ...)"

        active.add(marker)
        try:
            return super().__repr__()
        finally:
            active.discard(marker)

    def __deepcopy__(self, memo: dict[int, Any] | None = None):
        """Deep-copy like Pydantic, but register the copy *before* copying its fields.

        Pydantic's `BaseModel.__deepcopy__` builds the new object and deep-copies its `__dict__`
        first, and `copy.deepcopy` records the copy in `memo` only once that returns. A
        reference cycle that leads back to the object being copied -- a `MeasuringLineFunction`
        referencing the `ProcessInstrumentationFunction` it is composed under -- therefore meets
        an empty memo and makes a *second* copy, and the copied model's reference points at a
        detached duplicate instead of the object in the model. `model_copy(deep=True)`
        calls this method, so every deep copy of a model inherited the split.

        Registering the copy in `memo` before recursing makes every path to an object reach the
        one copy, which is what `deepcopy`'s memo exists for.
        """
        if memo is None:
            memo = {}
        existing = memo.get(id(self))
        if existing is not None:
            return existing
        cls = type(self)
        duplicate = cls.__new__(cls)
        memo[id(self)] = duplicate
        object.__setattr__(duplicate, "__dict__", deepcopy(self.__dict__, memo))
        object.__setattr__(duplicate, "__pydantic_extra__", deepcopy(self.__pydantic_extra__, memo))
        object.__setattr__(duplicate, "__pydantic_fields_set__", copy(self.__pydantic_fields_set__))
        private = getattr(self, "__pydantic_private__", None)
        object.__setattr__(
            duplicate,
            "__pydantic_private__",
            None
            if private is None
            else deepcopy(
                {key: value for key, value in private.items() if value is not PydanticUndefined},
                memo,
            ),
        )
        return duplicate

    def __str__(self) -> str:
        """Pydantic's `__str__` walks nested models too, so it needs the same cycle guard.

        The guard only changes the *re-entrant* render. On the normal path this still returns
        pydantic's `__str__` -- bare `field=value` pairs, no class name and no quoting -- so
        `str(model)` is unchanged for the acyclic models that are the common case.
        """
        active = getattr(_repr_state, "active", None)
        if active is None:
            active = _repr_state.active = set()

        marker = id(self)
        if marker in active:
            return f"{self.__repr_name__()}(id={getattr(self, 'id', None)!r}, ...)"

        active.add(marker)
        try:
            return super().__str__()
        finally:
            active.discard(marker)


class PyDexpiDataTypeBaseModel(ABC, BaseModel):
    """Base Model for the data type classes created for the dexpi data model, containing some overarching functionality"""

    # Model congigurations
    model_config = ConfigDict(validate_assignment=True, extra="forbid")

    # Physical quantity units are handled here rather than on PhysicalQuantity and
    # PhysicalQuantityVector because those two are generated: keeping the hook on the
    # hand-written base model confines the edit to one place and covers any future data type
    # with a unit. See pydexpi.pydexpi_classes.unit_resolution.
    @model_validator(mode="before")
    @classmethod
    def _coerce_physical_quantity_unit(cls, data: Any) -> Any:
        """Resolve a serialized ``unit`` into a real ``PhysicalQuantityUnit`` member.

        ``PhysicalQuantityUnit`` is an empty base enum, so pydantic validates ``unit`` with
        an ``is_instance_of`` check that no JSON payload can satisfy. Without this, a
        quantity could be read but never written from JSON -- not even by validating pydantic's
        own ``model_dump(mode="json")``.
        """
        if isinstance(data, dict) and "unit" in data:
            data = {**data, "unit": resolve_unit(data["unit"], _unit_base())}
        return data

    @model_serializer(mode="wrap", when_used="json")
    def _qualify_physical_quantity_unit(self, handler: Any) -> Any:
        """Serialize ``unit`` class-qualified, so the JSON dump round-trips.

        Pydantic writes a bare ``StrEnum`` as its value, which discards the enum class --
        and 15 unit literals ("Bar", "Millimetre", ...) are shared by two enums each, so the
        bare value alone cannot be resolved back. Emitting ``"PressureGaugeUnit.Bar"``, the
        spelling DEXPI XML DataReferences already use, keeps the dump reversible. Only the
        JSON mode is affected; ``model_dump()`` still yields the live member.

        Rewrites ``unit`` only where the handler already emitted it, so that a caller's
        ``exclude={"unit"}`` or a narrowing ``include=`` is not undone by re-inserting the
        field from the live model.
        """
        serialized = handler(self)
        unit = getattr(self, "unit", None)
        if isinstance(serialized, dict) and "unit" in serialized:
            if isinstance(unit, _unit_base()):
                serialized["unit"] = qualified_unit_name(unit)
        return serialized

    # Equality and hashing are by value. Both walk the fields in declaration order through the
    # helpers below, so that equal objects always hash equal; see `_data_type_fields`.
    def __eq__(self, other: object) -> bool:
        """Compare by value: the same class, and every field equal.

        Lists compare element by element, **in order**, where the specification declares them
        ordered (``is_ordered`` in the generated field metadata, as on
        ``PhysicalQuantityVector.values``), and as multisets otherwise; see `_data_type_fields`. Enum members compare by class as well as value, because
        ``StrEnum`` members of two enums are equal whenever their values are --
        ``PressureGaugeUnit.Bar`` and ``PressureAbsoluteUnit.Bar`` are different units.

        Parameters
        ----------
        other : object
            The object to compare with.

        Returns
        -------
        bool
            True when ``other`` is of the same class and every field is equal. Comparison with
            an object that is not a data type is left to the other operand.
        """
        if self is other:
            return True
        if not isinstance(other, PyDexpiDataTypeBaseModel):
            return NotImplemented
        if type(self) is not type(other):
            return False
        mine, theirs = self.__dict__, other.__dict__
        for name, unordered in _data_type_fields(type(self)):
            if not _values_equal(mine.get(name, _MISSING), theirs.get(name, _MISSING), unordered):
                return False
        return True

    def __hash__(self) -> int:
        """Hash by value, consistently with `__eq__`.

        Lists hash in order, so ``[0.3, 0.7]`` and ``[0.7, 0.3]`` hash differently -- a vector's
        values are ordered in DEXPI. An unordered field hashes its elements' hashes sorted, so
        the order it happens to be stored in does not change the hash.

        Returns
        -------
        int
            The hash of the class and all field values.
        """
        values = self.__dict__
        return hash(
            (
                type(self),
                *(
                    _value_hash(values.get(name, _MISSING), unordered)
                    for name, unordered in _data_type_fields(type(self))
                ),
            )
        )


# A list in a data type is ordered when the specification says so: the generated field carries
# `is_ordered` (`pydexpi.toolkits.list_order`, which cannot be imported here). DEXPI marks
# `PhysicalQuantityVector.Values` ordered, and order is what a vector means. The one data-type list
# it leaves unordered is `MultiLanguageString.SingleLanguageStrings`, a set of language variants of
# one text: the order they are stored in carries nothing, and a model that reorders them has not
# changed.
def _is_unordered_list(field: Any) -> bool:
    """Whether a field is a list the generated metadata does not declare ordered."""
    if not _is_list_annotation(field.annotation):
        return False
    extra = field.json_schema_extra
    return not (isinstance(extra, dict) and extra.get("is_ordered") is True)


def _is_list_annotation(annotation: Any) -> bool:
    """Whether an annotation is ``list[...]``, read from its text if it is still a forward
    reference -- ``MultiLanguageString.singleLanguageStrings`` names a class declared after it.
    """
    if get_origin(annotation) is list:
        return True
    text = getattr(annotation, "__forward_arg__", annotation)
    return isinstance(text, str) and text.replace(" ", "").startswith("list[")


# Stands in for a field missing from an instance's `__dict__` (possible after `model_construct`).
_MISSING = object()


@functools.cache
def _data_type_fields(cls: type) -> tuple[tuple[str, bool], ...]:
    """The fields of a data type class, each with whether it is an unordered list.

    Cached per class: `__eq__` and `__hash__` run often, and the field set of a class is fixed.
    """
    return tuple((name, _is_unordered_list(field)) for name, field in cls.model_fields.items())


def _values_equal(first: Any, second: Any, unordered: bool = False) -> bool:
    """Whether two data type field values are equal; see `PyDexpiDataTypeBaseModel.__eq__`."""
    if first is second:
        return True
    if isinstance(first, list) and isinstance(second, list):
        if len(first) != len(second):
            return False
        if not unordered:
            return all(_values_equal(a, b) for a, b in zip(first, second, strict=True))
        # A multiset comparison. Matching by equality rather than counting by hash keeps it
        # correct for elements that are equal without being the same; these lists are short.
        remaining = list(second)
        for item in first:
            for index, candidate in enumerate(remaining):
                if _values_equal(item, candidate):
                    del remaining[index]
                    break
            else:
                return False
        return True
    if isinstance(first, Enum) or isinstance(second, Enum):
        return type(first) is type(second) and first == second
    return bool(first == second)


def _value_hash(value: Any, unordered: bool = False) -> int:
    """Hash a data type field value, consistently with `_values_equal`."""
    if isinstance(value, list):
        hashes = [_value_hash(item) for item in value]
        return hash(tuple(sorted(hashes) if unordered else hashes))
    if isinstance(value, Enum):
        return hash((type(value), value))
    return hash(value)
